insert into public.email_automations(id,key,name,trigger_type,is_active) values('78e9961e-3d98-5d62-88e1-549dc368d658','course_make-dream','Осуществи мечту','course',false) on conflict(id) do nothing;
insert into public.courses(slug,title,kind,landing_url,access_days,day_card_extra_days,webinar_extra_days,automation_id,source_hash) values('make-dream','Осуществи мечту','course','https://zamkovoi.yoga/yoga3',90,3,5,'78e9961e-3d98-5d62-88e1-549dc368d658','255747f955e84a636ae7506ee79b4d7b2f833c419ab5a59e6d54d4029a0a1aae') on conflict(slug) do update set title=excluded.title,source_hash=excluded.source_hash;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('da6a0860-131d-53c2-b960-72c0c9a9eedd','78e9961e-3d98-5d62-88e1-549dc368d658','День 1: Состояния манипуры',1,0,'Осуществи мечту: День 1','{"ru":"Осуществи мечту: День 1"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png" alt="Осуществи мечту" width="504" height="247" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Благодарю Вас за решение пройти курс &quot;Осуществи мечту&quot;! Впереди у Вас путь длиной в 36 дней. Однако, время летит быстро. Поэтому не предвкушайте, не ожидайте, но находитесь в текущем моменте, и каждый день курса принимайте как главный в Вашей жизни, посвящая его самопознанию и развитию.</p><p></p><p>Курс начинался с названием &quot;Йога и социальный успех&quot;. Однако, в середине курса пришло понимание более глубокой цели - осуществление мечты. Как правило, мы живём в социуме, и путь к мечте проходит через социальный успех, но ведёт дальше. Поэтому в первых уроках курс называется &quot;Йога и социальный успех&quot;. Не пугайтесь, это именно данный курс.</p><p></p><p><strong>Расписание:</strong><br>Вы будете получать уроки ежедневно. Каждый день в 7:00 я буду отправлять Вам письмо со ссылкой на урок текущего дня. Хотя, вы можете открывать урок в Гармонизаторе во вкладке &quot;День&quot; начиная с полуночи текущего дня. А в письме будет ссылка на урок в браузере - на случай, если Вы не устанавливали Гармонизатор. Если в какой-то день, в указанное время, моё письмо не придёт, проверьте папочку &quot;Спам&quot;, а в Gmail ещё и &quot;Промоакции&quot;.</p><p></p><p>Есть небольшой нюанс с временем получения второго урока. Если вы записались на курс до 18:00, то второй урок вы получите в ближайшую полночь, и письмо - в 7:00 утра следующего дня. Если же вы записались после 18:00, то второй урок вы получите не в ближайшую, а в следующую полночь, и письмо со ссылкой на него придёт вам в 7:00 утра того дня. То есть у вас будет запас времени на случай, если вы не успеете выполнить практику в день записи на курс.</p><p></p><p>Итого, на примере одной недели Вас ожидает следующее расписание:<br>- День 1 (сегодня): теоретический урок<br>- День 2 (завтра): практический урок с асанами<br>- День 3: стратагема<br>- День 4: теоретический урок<br>- День 5: практика пранаямы<br>- День 6: стратагема<br>- День 7: стратагема</p><p></p><p>И так в течение четырёх недель. Пятая неделя курса посвящена перевариванию полученного. Это как шавасана после выполнения асан (которая, кстати, является важнейшим элементом практики). В течение пятой недели Вы будете получать уроки со стратагемами. В эти дни я рекомендую Вам продолжать практиковать асаны и пранаямы, в соответствии с уже пройденными на предыдущих неделях уроками. При этом наблюдайте за тем что происходит, и утверждайтесь в новом подходе к жизни. Это - важнейший этап курса, и для его эффективного прохождения необходимо находиться в открытом, расслабленном, и осознанном состоянии. Для этого Вам потребуются все возможные ресурсы.</p><p></p><p>Рекомендую Вам не откладывать просмотр уроков и выполнение практик. Двигайтесь в потоке расписания, и Вы получите лучший эффект. Стоит начать откладывать уроки, как они тут-же накопятся снежным комом.</p><p></p><p><strong>Вебинары и ответы на вопросы:</strong><br>Каждую неделю (обычно по субботам) я провожу в Zoom групповые онлайн-консультации (вебинары), на которых мы общаемся, поддерживаем мотивацию, обсуждаем возникающие трудности и вопросы. Перед каждой такой консультацией я буду высылать вам письмо с указанием даты и времени её проведения, а также ссылкой для того, чтобы к ней присоединиться. То, что интересно вам, наверняка будет интересно и многим другим. Поэтому, обсуждение вопросов на групповых консультациях наиболее эффективно. Если случится так, что время консультации окажется вам неудобным, в этом случае пришлите ваши вопросы имейлом до её начала. Я отвечу на них на консультации, а вам пришлю ссылку на запись, чтобы вы могли посмотреть её в удобное вам время. Записи консультаций сохраняются в течение одной недели.</p><div style="margin:0px 0 0px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-01-43cae0428661.jpg" alt="картинка письма" width="504" height="284" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p><strong>Стратагемы:</strong><br>Проходя курс, Вы также глубоко освоите древнекитайский военный трактат 36 стратагем. Знание стратагем поможет Вам находить нарушения законов манипуры, а также быстрей двигаться в направлении своей мечты, а точней - той цели, которую Вы поставили на курс. Если Вы затрудняетесь определить свою цель, не волнуйтесь, через несколько дней Вы её определите - этой теме посвящён специальный урок. И ещё... Вам может показаться соблазнительным найти в интернете, и прочитать все стратагемы наперёд. Однако, не делайте этого, не следуйте привычным шаблонам. Отнеситесь к стратагемам с уважением, посвятив каждой из них один день своей жизни. И тогда стратагемы ответят Вам любовью и мудростью.</p><p></p><p><strong>Техника безопасности:</strong><br>Я забочусь о Вашем здоровье и напоминаю, что только Вы несёте ответственность за адекватность выполнения рекомендованных в данном курсе заданий (то есть асан, пранаям и медитаций) Вашим физическим возможностям и психическому состоянию. В случае необходимости, целесообразность выполнения заданий должна согласовываться с врачом. Важно понимать, что это онлайн курс, и я не могу проконтролировать состояние каждого, кто на него записывается. А люди бывают разные. У каждого есть физические и психологические особенности. Я с любовью отобрал, и предлагаю Вам максимально эффективные техники, необходимые для достижения целей данного курса. Но я не несу ответственности за последствия их применения. Пожалуйста, будьте внимательны к своему состоянию.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть первый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly">Перейти к урокам первого дня</a></p><p></p><p>Желаю Вам плодотворного прохождения курса!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png\" alt=\"Осуществи мечту\" width=\"504\" height=\"247\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Благодарю Вас за решение пройти курс &quot;Осуществи мечту&quot;! Впереди у Вас путь длиной в 36 дней. Однако, время летит быстро. Поэтому не предвкушайте, не ожидайте, но находитесь в текущем моменте, и каждый день курса принимайте как главный в Вашей жизни, посвящая его самопознанию и развитию.</p><p></p><p>Курс начинался с названием &quot;Йога и социальный успех&quot;. Однако, в середине курса пришло понимание более глубокой цели - осуществление мечты. Как правило, мы живём в социуме, и путь к мечте проходит через социальный успех, но ведёт дальше. Поэтому в первых уроках курс называется &quot;Йога и социальный успех&quot;. Не пугайтесь, это именно данный курс.</p><p></p><p><strong>Расписание:</strong><br>Вы будете получать уроки ежедневно. Каждый день в 7:00 я буду отправлять Вам письмо со ссылкой на урок текущего дня. Хотя, вы можете открывать урок в Гармонизаторе во вкла