insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('64020e93-f9f4-5d2a-967a-39f02af7a06d','78e9961e-3d98-5d62-88e1-549dc368d658','День 11: Поток манипуры, и законы потоков',11,0,'Осуществи мечту: День 11','{"ru":"Осуществи мечту: День 11"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png" alt="Осуществи мечту" width="504" height="247" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня Вы узнаете что нужно, чтобы войти в поток манипуры, как в нём двигаться не вылетая, и как определять время когда пора переключаться между потоками.</p><div style="margin:0px 0 0px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-11-6ae544433b33.jpg" alt="картинка письма" width="504" height="284" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Нажмите кнопку ниже, чтобы открыть одиннадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png\" alt=\"Осуществи мечту\" width=\"504\" height=\"247\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня Вы узнаете что нужно, чтобы войти в поток манипуры, как в нём двигаться не вылетая, и как определять время когда пора переключаться между потоками.</p><div style=\"margin:0px 0 0px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-11-6ae544433b33.jpg\" alt=\"картинка письма\" width=\"504\" height=\"284\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Нажмите кнопку ниже, чтобы открыть одиннадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-make-dream-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png","alt":"Осуществи мечту","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":294},{"id":"make-dream-11-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня Вы узнаете что нужно, чтобы войти в поток манипуры, как в нём двигаться не вылетая, и как определять время когда пора переключаться между потоками.</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0},{"id":"make-dream-11-text-image-1","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-11-6ae544433b33.jpg","alt":"картинка письма","href":"","width":"100%","align":"center","marginTop":0,"marginBottom":0,"naturalWidth":599,"naturalHeight":337},{"id":"make-dream-11-text-2","type":"text","html":"<p>Нажмите кнопку ниже, чтобы открыть одиннадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('make-dream-11','make-dream',11,1,'День 11: Поток манипуры, и законы потоков','[{"type":"text","markdown":"Как Вы думаете - когда индейцы племени Тумба-Юмба поклоняются волшебному дереву, их просьбы исполняются? Скорей всего да, иначе индейцы поклонялись бы чему-нибудь другому. Можем ли мы рассматривать поток манипуры как что-то одухотворённое, и взаимодействовать с ним как с чем-то обладающим сознанием? Пройдя этот урок Вы узнаете это наверняка :)"},{"type":"video","vimeoId":"1105071364"},{"type":"text","markdown":"\n\n**Стратагема 11:**"},{"type":"video","vimeoId":"322184647"},{"type":"text","markdown":"\n\n**Задание к уроку:**\nОпределите действие, которое в данный момент времени социум от Вас ожидает, но которое Вы по каким-то причинам не делаете. А также перечислите в тетрадке бонусы, которые Вы можете получить выполнив это действие, и к чему Вы сможете прийти в дальнейшем."}]'::jsonb,'64020e93-f9f4-5d2a-967a-39f02af7a06d') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('f6f313cd-9e76-5b92-a20b-9b3322c7e35a','78e9961e-3d98-5d62-88e1-549dc368d658','День 12: Пранаяма',12,0,'Осуществи мечту: День 12','{"ru":"Осуществи мечту: День 12"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png" alt="Осуществи мечту" width="504" height="247" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Знакомясь со стратагемами, Вы могли обнаружить у себя эмоциональные реакции в адрес некоторых из них. Это говорит о том, что в деятельность манипуры вмешивается анахата в качестве этического цензора. И это вмешательство ограничивает свободу проявлений манипуры. Манипура предусматривает тотальность движения к цели. И она прекрасно &quot;знает&quot; кратчайший путь. Сегодня мы освоим пранаяму, которая при регулярном выполнении помогает &quot;разлепить&quot; анахату и манипуру. Занятие пройдёт в красивейшеем месте с мощнейшей энергетикой.</p><div style="margin:0px 0 0px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-12-61b5172fcd01.jpg" alt="картинка письма" width="504" height="284" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Нажмите кнопку ниже, чтобы открыть двенадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png\" alt=\"Осуществи мечту\" width=\"504\" height=\"247\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Знакомясь со стратагемами, Вы могли обнаружить у себя эмоциональные реакции в адрес некоторых из них. Это говорит о том, что в деятельность манипуры вмешивается анахата в качестве этического цензора. И это вмешательство ограничивает свободу проявлений манипуры. Манипура предусматривает тотальность движения к цели. И она прекрасно &quot;знает&quot; кратчайший путь. Сегодня мы освоим пранаяму, которая при регулярном выполнении помогает &quot;разлепить&quot; анахату и манипуру. Занятие пройдёт в красивейшеем месте с мощнейшей энергетикой.</p><div style=\"margin:0px 0 0px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-12-61b5172fcd01.jpg\" alt=\"картинка письма\" width=\"504\" height=\"284\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Нажмите кнопку ниже, чтобы открыть двенадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-make-dream-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png","alt":"Осуществи мечту","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":294},{"id":"make-dream-12-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Знакомясь со стратагемами, Вы могли обнаружить у себя эмоциональные реакции в адрес некоторых из них. Это говорит о том, что в деятельность манипуры вмешивается анахата в качестве этического цензора. И это вмешательство ограничивает свободу проявлений манипуры. Манипура предусматривает тотальность движения к цели. И она прекрасно &quot;знает&quot; кратчайший путь. Сегодня мы освоим пранаяму, которая при регулярном выполнении помогает &quot;разлепить&quot; анахату и манипуру. Занятие пройдёт в красивейшеем месте с мощнейшей энергетикой.</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0},{"id":"make-dream-12-text-image-1","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-12-61b5172fcd01.jpg","alt":"картинка письма","href":"","width":"100%","align":"center","marginTop":0,"marginBottom":0,"naturalWidth":599,"naturalHeight":337},{"id":"make-dream-12-text-2","type":"text","html":"<p>Нажмите кнопку ниже, чтобы открыть двенадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('make-dream-12','make-dream',12,1,'День 12: Пранаяма','[{"type":"text","markdown":"Сегодня мы закрепим вьяяму, и выполним мощнейшую пранаяму, разминающую диафрагму, массирующую органы брюшной полости, и перекачивающую энергию между манипурой и анахатой, а также \"разлепляющую\" эти две чакры.\n\n**Внимание:** При язве желудка или если были операции на брюшную полость проконсультируйтесь со своим лечащим врачом прежде чем выполнять эту пранаяму. Также эту пранаяму нужно пропустить женщинам во время месячных и беременности. При мигрени, а также существенно повышенном или пониженном давлении будьте осторожны, прислушивайтесь к своим ощущениям.\n\n**Техника безопасности:** Обязательно удерживайте мулабандху при задержке на вдохе, и джаландхара бандху при задержке на выдохе. При выполнении джаландхара бандхи оставляйте голосовую щель приоткрытой для прохождения воздуха."},{"type":"video","vimeoId":"315556222"},{"type":"text","markdown":"\n\n**Стратагема:**"},{"type":"video","vimeoId":"315616701"},{"type":"text","markdown":"\n\n**Задание к уроку:**\nПри отсутствии противопоказаний, выполняйте эту пранаяму ежедневно в течение 10 минут до следующего урока, на котором мы будем осваивать пранаямы."}]'::jsonb,'f6f313cd-9e76-5b92-a20b-9b3322c7e35a') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('d6452029-52c0-5207-b963-311033a5aad7','78e9961e-3d98-5d62-88e1-549dc368d658','День 13: Стратагема',13,0,'Осуществи мечту: День 13','{"ru":"Осуществи мечту: День 13"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png" alt="Осуществи мечту" width="504" height="247" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня Вас ожидает новая стратагема. Взгляните на мир глазами серпентолога :)</p><div style="margin:0px 0 0px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-13-655194b3f7a3.jpg" alt="картинка письма" width="504" height="284" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Нажмите кнопку ниже, чтобы открыть тринадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png\" alt=\"Осуществи мечту\" width=\"504\" height=\"247\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня Вас ожидает новая стратагема. Взгляните на мир глазами серпентолога :)</p><div style=\"margin:0px 0 0px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-13-655194b3f7a3.jpg\" alt=\"картинка письма\" width=\"504\" height=\"284\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Нажмите кнопку ниже, чтобы открыть тринадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-make-dream-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png","alt":"Осуществи мечту","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":294},{"id":"make-dream-13-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня Вас ожидает новая стратагема. Взгляните на мир глазами серпентолога :)</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0},{"id":"make-dream-13-text-image-1","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-13-655194b3f7a3.jpg","alt":"картинка письма","href":"","width":"100%","align":"center","marginTop":0,"marginBottom":0,"naturalWidth":599,"naturalHeight":337},{"id":"make-dream-13-text-2","type":"text","html":"<p>Нажмите кнопку ниже, чтобы открыть тринадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}