insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('d0d14fa5-08eb-5de6-8a25-46232f514c5d','78e9961e-3d98-5d62-88e1-549dc368d658','День 14: Стратагема',14,0,'Осуществи мечту: День 14','{"ru":"Осуществи мечту: День 14"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png" alt="Осуществи мечту" width="504" height="247" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Продолжайте усваивать знание, полученное на предыдущих уроках. Практикуйте, превращая его в опыт и в мудрость. А также сегодня Вас ожидает новая стратагема.</p><div style="margin:0px 0 0px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-14-43c153399e2f.jpg" alt="картинка письма" width="504" height="284" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Нажмите кнопку ниже, чтобы открыть четырнадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png\" alt=\"Осуществи мечту\" width=\"504\" height=\"247\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Продолжайте усваивать знание, полученное на предыдущих уроках. Практикуйте, превращая его в опыт и в мудрость. А также сегодня Вас ожидает новая стратагема.</p><div style=\"margin:0px 0 0px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-14-43c153399e2f.jpg\" alt=\"картинка письма\" width=\"504\" height=\"284\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Нажмите кнопку ниже, чтобы открыть четырнадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-make-dream-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png","alt":"Осуществи мечту","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":294},{"id":"make-dream-14-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Продолжайте усваивать знание, полученное на предыдущих уроках. Практикуйте, превращая его в опыт и в мудрость. А также сегодня Вас ожидает новая стратагема.</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0},{"id":"make-dream-14-text-image-1","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-14-43c153399e2f.jpg","alt":"картинка письма","href":"","width":"100%","align":"center","marginTop":0,"marginBottom":0,"naturalWidth":599,"naturalHeight":337},{"id":"make-dream-14-text-2","type":"text","html":"<p>Нажмите кнопку ниже, чтобы открыть четырнадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('make-dream-14','make-dream',14,1,'День 14: Стратагема','[{"type":"video","vimeoId":"317751869"}]'::jsonb,'d0d14fa5-08eb-5de6-8a25-46232f514c5d') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('5820c7ab-22cc-5ea5-a096-7cbc99976e37','78e9961e-3d98-5d62-88e1-549dc368d658','День 15: Причины оттоков энергии, и простейший способ их прекращения',15,0,'Осуществи мечту: День 15','{"ru":"Осуществи мечту: День 15"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png" alt="Осуществи мечту" width="504" height="247" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Куда девается энергия нереализованных желаний? Почему она сливается вопреки нашей на то воле? Пройдите этот урок, чтобы узнать ответы.</p><div style="margin:0px 0 0px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-15-550fd2e6fde5.jpg" alt="картинка письма" width="504" height="284" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Нажмите кнопку ниже, чтобы открыть пятнадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png\" alt=\"Осуществи мечту\" width=\"504\" height=\"247\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Куда девается энергия нереализованных желаний? Почему она сливается вопреки нашей на то воле? Пройдите этот урок, чтобы узнать ответы.</p><div style=\"margin:0px 0 0px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-15-550fd2e6fde5.jpg\" alt=\"картинка письма\" width=\"504\" height=\"284\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Нажмите кнопку ниже, чтобы открыть пятнадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-make-dream-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png","alt":"Осуществи мечту","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":294},{"id":"make-dream-15-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Куда девается энергия нереализованных желаний? Почему она сливается вопреки нашей на то воле? Пройдите этот урок, чтобы узнать ответы.</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0},{"id":"make-dream-15-text-image-1","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-15-550fd2e6fde5.jpg","alt":"картинка письма","href":"","width":"100%","align":"center","marginTop":0,"marginBottom":0,"naturalWidth":599,"naturalHeight":337},{"id":"make-dream-15-text-2","type":"text","html":"<p>Нажмите кнопку ниже, чтобы открыть пятнадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('make-dream-15','make-dream',15,1,'День 15: Причины оттоков энергии, и простейший способ их прекращения','[{"type":"text","markdown":"Поток энергии прямиком несёт Вас к осуществлению каждого желания которое Вы принимаете в качестве своей цели. Однако, бывает что Вы вдруг обнаруживаете себя уже без цели, без желания, и без энергии.... В общем-то это довольно частая ситуация. Так куда-же делась энергия? Почему цель оказалась не достигнутой? Я объясняю данное явление наличием у нас психологических вставок. И в этом уроке предлагаю несколько способов их обнаружения и преодоления. А также мы на практике попробуем пройти кратчайшим путём - обновлением самоиндентичности :)"},{"type":"video","vimeoId":"1249170887"},{"type":"text","markdown":"\n\nВажно иметь в виду, что вставки на чакре отнюдь не мешают её развитию (тема дня 8), но помогают обнаружить и ощутить нюансы вкуса определённых энергий, тем самым обогащая Ваш духовный опыт, и развивая чакру. Так принимайте их \"дары\" :)\n\nИ ещё - в медитации название самоидентичности должно прийти само, из пустоты, из Вашего внутреннего мира. И обычно это инсайт, это не что-то вялое, являющееся результатом длительных размышлений. В момент осознания Вы переживаее яркие эмоции радости важного духовного шага, на уровне тела можете чувствовать дрожь, мурашки, волны энергии...\n\n**Стратагема:**"},{"type":"video","vimeoId":"318026797"},{"type":"text","markdown":"\n\n**Задания:**\n1. В течение дня как можно чаще возвращайтесь в состояние новой самоидентичности, и дольше в нём находитесь.\n2. В результате перехода в новую самоидентичность сделайте очередной шаг в направлении своей цели по плану, построенному на уроке 4."}]'::jsonb,'5820c7ab-22cc-5ea5-a096-7cbc99976e37') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('c0b1aaee-36b6-56ad-9111-3243fb8bb36c','78e9961e-3d98-5d62-88e1-549dc368d658','День 16: Практика: Гибкость и баланс в проявлениях силы',16,0,'Осуществи мечту: День 16','{"ru":"Осуществи мечту: День 16"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png" alt="Осуществи мечту" width="504" height="247" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня Вас ожидает мощный практический урок. Я собрал в нём несложные асаны, которые в комплексе работают очень эффективно - развивая способность быть гибким и осознанным в ситуациях, где включается манипура. И на физическом уровне они очень полезны для позвоночника. Однако, если у Вас есть заболевания позвоночника, в зависимости от тяжести, со многими асанами будьте очень остороны.</p><div style="margin:0px 0 0px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-16-80a45277cefe.jpg" alt="картинка письма" width="504" height="284" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Нажмите кнопку ниже, чтобы открыть шестнадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png\" alt=\"Осуществи мечту\" width=\"504\" height=\"247\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня Вас ожидает мощный практический урок. Я собрал в нём несложные асаны, которые в комплексе работают очень эффективно - развивая способность быть гибким и осознанным в ситуациях, где включается манипура. И на физическом уровне они очень полезны для позвоночника. Однако, если у Вас есть заболевания позвоночника, в зависимости от тяжести, со многими асанами будьте очень остороны.</p><div style=\"margin:0px 0 0px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-16-80a45277cefe.jpg\" alt=\"картинка письма\" width=\"504\" height=\"284\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Нажмите кнопку ниже, чтобы открыть шестнадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-make-dream-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png","alt":"Осуществи мечту","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":294},{"id":"make-dream-16-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня Вас ожидает мощный практический урок. Я собрал в нём несложные асаны, которые в комплексе работают очень эффективно - развивая способность быть гибким и осознанным в ситуациях, где включается манипура. И на физическом уровне они очень полезны для позвоночника. Однако, если у Вас есть заболевания позвоночника, в зависимости от тяжести, со многими асанами будьте очень остороны.</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0},{"id":"make-dream-16-text-image-1","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-16-80a45277cefe.jpg","alt":"картинка письма","href":"","width":"100%","align":"center","marginTop":0,"marginBottom":0,"naturalWidth":599,"naturalHeight":337},{"id":"make-dream-16-text-2","type":"text","html":"<p>Нажмите кнопку ниже, чтобы открыть шестнадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('make-dream-16','make-dream',16,1,'День 16: Практика: Гибкость и баланс в проявлениях силы','[{"type":"text","markdown":"В этом уроке мы выполним вьяяму, а затем комплекс карана-крамы, направив своё намерение на развитие гибкости и баланса (осознанности) в проявлениях силы."},{"type":"video","vimeoId":"317654302"},{"type":"text","markdown":"\n\n**Стратагема:**"},{"type":"video","vimeoId":"317683504"},{"type":"text","markdown":"\n\n**Задание к уроку:**\nПри отсутствии противопоказаний, выполняйте данный комплекс ежедневно до следующего урока с практикой асан."}]'::jsonb,'c0b1aaee-36b6-56ad-9111-3243fb8bb36c') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('fdd0c50d-58a0-5e44-a922-c0bcb025d272','78e9961e-3d98-5d62-88e1-549dc368d658','День 17: Стратагема',17,0,'Осуществи мечту: День 17','{"ru":"Осуществи мечту: День 17"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png" alt="Осуществи мечту" width="504" height="247" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня я подготовил для Вас новую стратагему. Помимо её освоения, направьте своё внимание на закрепление вчерашнего комплекса асан. Также наблюдайте ответную реакцию социума на Ваши действия, делайте выводы, и предпринимайте следующие шаги.</p><div style="margin:0px 0 0px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-17-f3bb6d7405d1.jpg" alt="картинка письма" width="504" height="284" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Нажмите кнопку ниже, чтобы открыть семнадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png\" alt=\"Осуществи мечту\" width=\"504\" height=\"247\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня я подготовил для Вас новую стратагему. Помимо её освоения, направьте своё внимание на закрепление вчерашнего комплекса асан. Также наблюдайте ответную реакцию социума на Ваши действия, делайте выводы, и предпринимайте следующие шаги.</p><div style=\"margin:0px 0 0px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-17-f3bb6d7405d1.jpg\" alt=\"картинка письма\" width=\"504\" height=\"284\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Нажмите кнопку ниже, чтобы открыть семнадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-make-dream-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png","alt":"Осуществи мечту","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":294},{"id":"make-dream-17-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня я подготовил для Вас новую стратагему. Помимо её освоения, направьте своё внимание на закрепление вчерашнего комплекса асан. Также наблюдайте ответную реакцию социума на Ваши действия, делайте выводы, и предпринимайте следующие шаги.</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0},{"id":"make-dream-17-text-image-1","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-17-f3bb6d7405d1.jpg","alt":"картинка письма","href":"","width":"100%","align":"center","marginTop":0,"marginBottom":0,"naturalWidth":599,"naturalHeight":337},{"id":"make-dream-17-text-2","type":"text","html":"<p>Нажмите кнопку ниже, чтобы открыть семнадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('make-dream-17','make-dream',17,1,'День 17: Стратагема','[{"type":"text","markdown":"Пришло время проверить - ворона Вы или лисица (или известной нам басни Крылова). В общем-то, история одна, персонажи связаны, и пройдя стадию вороны, Вы автоматически переключитесь в лисицу. Но данная стратагема добавит осознанности в Ваш день, и ускорит развитие."},{"type":"video","vimeoId":"318024136"}]'::jsonb,'fdd0c50d-58a0-5e44-a922-c0bcb025d272') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('b6b5c62d-0d59-5d21-9ca5-30fb1fc6f02a','78e9961e-3d98-5d62-88e1-549dc368d658','День 18: Законы манипуры',18,0,'Осуществи мечту: День 18','{"ru":"Осуществи мечту: День 18"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png" alt="Осуществи мечту" width="504" height="247" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>После прохождения предыдущего урока, возможно, у Вас ещё остались оттоки энергии. Действительно, утвердиться в новой самоидентичности бывает не просто. И тут Вам на помощь придёт знание чакральных законов манипуры. Именно их Вы сегодня будете осваивать.</p><div style="margin:0px 0 0px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-18-d62166f928f0.jpg" alt="картинка письма" width="504" height="284" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Нажмите кнопку ниже, чтобы открыть восемнадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png\" alt=\"Осуществи мечту\" width=\"504\" height=\"247\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>После прохождения предыдущего урока, возможно, у Вас ещё остались оттоки энергии. Действительно, утвердиться в новой самоидентичности бывает не просто. И тут Вам на помощь придёт знание чакральных законов манипуры. Именно их Вы сегодня будете осваивать.</p><div style=\"margin:0px 0 0px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-18-d62166f928f0.jpg\" alt=\"картинка письма\" width=\"504\" height=\"284\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Нажмите кнопку ниже, чтобы открыть восемнадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-make-dream-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png","alt":"Осуществи мечту","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":294},{"id":"make-dream-18-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>После прохождения предыдущего урока, возможно, у Вас ещё остались оттоки энергии. Действительно, утвердиться в новой самоидентичности бывает не просто. И тут Вам на помощь придёт знание чакральных законов манипуры. Именно их Вы сегодня будете осваивать.</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0},{"id":"make-dream-18-text-image-1","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-18-d62166f928f0.jpg","alt":"картинка письма","href":"","width":"100%","align":"center","marginTop":0,"marginBottom":0,"naturalWidth":599,"naturalHeight":337},{"id":"make-dream-18-text-2","type":"text","html":"<p>Нажмите кнопку ниже, чтобы открыть восемнадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('make-dream-18','make-dream',18,1,'День 18: Законы манипуры','[{"type":"text","markdown":"Подготовьте блокнот и ручку, чтобы в процессе прохождения данного урока записывать идеи, вызывающие резонанс у Вас в теле. Ваша задача - обнаружить и точно сформулировать наиболее актуальные для Вас законы манипуры. То есть те законы, которые Вы часто нарушаете. И далее для каждого такого закона продумайте альтернативную гармоничную форму своего поведения. Рассмотрите в качестве примера несколько ситуаций, в которых Вы ранее \"сыпались\", и перепроживите их по-новому. После этого закрепляйте новую форму поведения в реальных ситуациях, коорые непременно начнёт подбрасывать Вам жизнь."},{"type":"video","vimeoId":"1249170887"},{"type":"text","markdown":"\n\n**Стратагема:**"},{"type":"video","vimeoId":"322184863"},{"type":"text","markdown":"\n\n**Задания к уроку:**\n- Сформулируйте наиболее актуальные для Вас чакральные законы манипуры.\n- Распечатайте формулировку каждого закона на отдельном листе А4, и повесьте эти личты на стенах Вашей комнаты.\n- Нарабатывайте выполнение этих законов. И только когда почувствуете, что достаточно утвердились новых формах поведения, снимите со стен листочки с законами."}]'::jsonb,'b6b5c62d-0d59-5d21-9ca5-30fb1fc6f02a') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('b71c2967-1fb7-50ff-8944-ac87dee7b200','78e9961e-3d98-5d62-88e1-549dc368d658','День 19: Пранаяма очищения огнём',19,0,'Осуществи мечту: День 19','{"ru":"Осуществи мечту: День 19"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png" alt="Осуществи мечту" width="504" height="247" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Погодите, не кушайте!!! Сегодня я подготовил для Вас очистительную практику, которую нужно выполнять на пустой желудок :)</p><p></p><p>Надеюсь, Вам понравится состояние, которое она даёт, и Вы будете выполнять её каждое утро, чтобы наполняться энергией, а также сжигать препятствия на пути к Вашей мечте - прежде всего те, которые соматизируются в теле, и опускают Ваш жизненный тонус.</p><div style="margin:0px 0 0px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-19-a133ba9817be.jpg" alt="картинка письма" width="504" height="284" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Нажмите кнопку ниже, чтобы открыть девятнадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>Мощного Вам дня!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png\" alt=\"Осуществи мечту\" width=\"504\" height=\"247\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Погодите, не кушайте!!! Сегодня я подготовил для Вас очистительную практику, которую нужно выполнять на пустой желудок :)</p><p></p><p>Надеюсь, Вам понравится состояние, которое она даёт, и Вы будете выполнять её каждое утро, чтобы наполняться энергией, а также сжигать препятствия на пути к Вашей мечте - прежде всего те, которые соматизируются в теле, и опускают Ваш жизненный тонус.</p><div style=\"margin:0px 0 0px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-19-a133ba9817be.jpg\" alt=\"картинка письма\" width=\"504\" height=\"284\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Нажмите кнопку ниже, чтобы открыть девятнадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Мощного Вам дня!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-make-dream-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png","alt":"Осуществи мечту","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":294},{"id":"make-dream-19-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Погодите, не кушайте!!! Сегодня я подготовил для Вас очистительную практику, которую нужно выполнять на пустой желудок :)</p><p></p><p>Надеюсь, Вам понравится состояние, которое она даёт, и Вы будете выполнять её каждое утро, чтобы наполняться энергией, а также сжигать препятствия на пути к Вашей мечте - прежде всего те, которые соматизируются в теле, и опускают Ваш жизненный тонус.</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0},{"id":"make-dream-19-text-image-1","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-19-a133ba9817be.jpg","alt":"картинка письма","href":"","width":"100%","align":"center","marginTop":0,"marginBottom":0,"naturalWidth":599,"naturalHeight":337},{"id":"make-dream-19-text-2","type":"text","html":"<p>Нажмите кнопку ниже, чтобы открыть девятнадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Мощного Вам дня!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('make-dream-19','make-dream',19,1,'День 19: Пранаяма очищения огнём','[{"type":"text","markdown":"Сегодня мы выполним связку из нескольких пранаям, которые мощно очищают сферу манипуры. Центральное место занимает Агнисара дхаути крийя. Её обычно относят к шаткармам, то есть к очистительным процедурам. \"Агни\" переводится как огонь, \"Сар\" - сущность, \"Дхаути\" - внутреннее очищение. В Гхеранда-самхите эта практика описывается так: \"Тесно прижми узел пупа к позвоночнику (втягивая живот) 100 раз. Это - Агнисара Дхаути, которая приносит йогину успех в йоге, устраняет болезни желудка и усиливает огонь пищеварения\"."},{"type":"video","vimeoId":"318856507"},{"type":"text","markdown":"\n\nС точки зрения энергетики, \"огонь пищеварения\" - это то, что переваривает поступающую в нас энергию. Потому что энергия и есть наша пища! Однако, есть множество видов энергии, которые мы не в состоянии \"переварить\". И такие энергии фиксируются где-то в нашем тонком теле, влияя на нас (как правило негативно), и ограничивая нашу свободу. Например, Вас заставляют что-то делать, Вы не хотите, но делаете. Вы хотите сказать \"нет\", но по ряду причин не говорите. Эта энергия где-то накапливается. Если её накопится много, то \"несварение\" начнёт проявляться уже на физическом уровне - в виде проблем с пищеварением, а далее могут проявиться заболевания ЖКТ. Разумеется, лучше до этого не доводить. И Агнисара дхаути крийя усиливая внутренний огонь, помогает усвоить непереваренную энергию. Поэтому я рекомендую рассматривать Агнисара дхаути крийю как обязательную утреннюю очистительную процедуру, наряду с чисткой зубов.\n\n**Стратагема:**"},{"type":"video","vimeoId":"317685259"},{"type":"text","markdown":"\n\n**Задание к уроку:**\nВыполните комплекс асан, дополнив его пранаямами, рассмотренными в данном уроке. И далее ежедневно выполняйте комплекс уддияна-бандха с массажем и агнисара дхаути крийю каждое утро, как минимум до окончания данного курса. Постепенно увеличивайте к-во циклов агнисара дхаути крийи. Но не впадайте в фанатизм. Развивайтесь плавно.\n======================\n\n**Ответ на вопрос:**\nКак поступать - идти за своими внутренними ощущениями или надо всё-таки было перебороть себя и сделать ещё очистительные пранаямы перед шавасаной?"},{"type":"video","vimeoId":"1105073275"}]'::jsonb,'b71c2967-1fb7-50ff-8944-ac87dee7b200') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('d23a17e2-b339-596d-a85d-ef8a8724bf4b','78e9961e-3d98-5d62-88e1-549dc368d658','День 20: Стратагема',20,0,'Осуществи мечту: День 20','{"ru":"Осуществи мечту: День 20"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png" alt="Осуществи мечту" width="504" height="247" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Давно не были на рыбалке? Сегодня Вам предстоит освоить искусство мутить воду, чтобы ловить рыбу :)</p><div style="margin:0px 0 0px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-20-b3258bd63f4f.jpg" alt="картинка письма" width="504" height="284" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Нажмите кнопку ниже, чтобы открыть двадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png\" alt=\"Осуществи мечту\" width=\"504\" height=\"247\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Давно не были на рыбалке? Сегодня Вам предстоит освоить искусство мутить воду, чтобы ловить рыбу :)</p><div style=\"margin:0px 0 0px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-20-b3258bd63f4f.jpg\" alt=\"картинка письма\" width=\"504\" height=\"284\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Нажмите кнопку ниже, чтобы открыть двадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-make-dream-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png","alt":"Осуществи мечту","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":294},{"id":"make-dream-20-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Давно не были на рыбалке? Сегодня Вам предстоит освоить искусство мутить воду, чтобы ловить рыбу :)</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0},{"id":"make-dream-20-text-image-1","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-20-b3258bd63f4f.jpg","alt":"картинка письма","href":"","width":"100%","align":"center","marginTop":0,"marginBottom":0,"naturalWidth":599,"naturalHeight":337},{"id":"make-dream-20-text-2","type":"text","html":"<p>Нажмите кнопку ниже, чтобы открыть двадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
