insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('8b83c365-6e09-5047-85fe-b853ddb7d2e4','78e9961e-3d98-5d62-88e1-549dc368d658','День 21: Стратагема',21,0,'Осуществи мечту: День 21','{"ru":"Осуществи мечту: День 21"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png" alt="Осуществи мечту" width="504" height="247" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня задача - освоить искусство маскировки и скрытых манёвров. В этом Вам поможет стратагема 21.</p><div style="margin:0px 0 0px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-21-fa12aa87bbee.jpg" alt="картинка письма" width="504" height="284" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Нажмите кнопку ниже, чтобы открыть двадцать первый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png\" alt=\"Осуществи мечту\" width=\"504\" height=\"247\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня задача - освоить искусство маскировки и скрытых манёвров. В этом Вам поможет стратагема 21.</p><div style=\"margin:0px 0 0px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-21-fa12aa87bbee.jpg\" alt=\"картинка письма\" width=\"504\" height=\"284\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Нажмите кнопку ниже, чтобы открыть двадцать первый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-make-dream-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png","alt":"Осуществи мечту","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":294},{"id":"make-dream-21-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня задача - освоить искусство маскировки и скрытых манёвров. В этом Вам поможет стратагема 21.</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0},{"id":"make-dream-21-text-image-1","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-21-fa12aa87bbee.jpg","alt":"картинка письма","href":"","width":"100%","align":"center","marginTop":0,"marginBottom":0,"naturalWidth":599,"naturalHeight":337},{"id":"make-dream-21-text-2","type":"text","html":"<p>Нажмите кнопку ниже, чтобы открыть двадцать первый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
