insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('f713d317-34fe-511a-95be-9da227b7dcb6','78e9961e-3d98-5d62-88e1-549dc368d658','День 22: Психологическое айкидо',22,0,'Осуществи мечту: День 22','{"ru":"Осуществи мечту: День 22"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png" alt="Осуществи мечту" width="504" height="247" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Как выходить победителем из сложных ситуаций? Вы уже владеете широким арсеналом стратагем. А, пройдя этот урок, Вы узнаете ещё несколько эффектных приёмов, которые сможете применять во благо себе и людям.</p><div style="margin:0px 0 0px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-22-707d7b52fc2c.jpg" alt="картинка письма" width="504" height="284" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Нажмите кнопку ниже, чтобы открыть двадцать второй урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png\" alt=\"Осуществи мечту\" width=\"504\" height=\"247\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Как выходить победителем из сложных ситуаций? Вы уже владеете широким арсеналом стратагем. А, пройдя этот урок, Вы узнаете ещё несколько эффектных приёмов, которые сможете применять во благо себе и людям.</p><div style=\"margin:0px 0 0px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-22-707d7b52fc2c.jpg\" alt=\"картинка письма\" width=\"504\" height=\"284\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Нажмите кнопку ниже, чтобы открыть двадцать второй урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-make-dream-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png","alt":"Осуществи мечту","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":294},{"id":"make-dream-22-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Как выходить победителем из сложных ситуаций? Вы уже владеете широким арсеналом стратагем. А, пройдя этот урок, Вы узнаете ещё несколько эффектных приёмов, которые сможете применять во благо себе и людям.</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0},{"id":"make-dream-22-text-image-1","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-22-707d7b52fc2c.jpg","alt":"картинка письма","href":"","width":"100%","align":"center","marginTop":0,"marginBottom":0,"naturalWidth":600,"naturalHeight":338},{"id":"make-dream-22-text-2","type":"text","html":"<p>Нажмите кнопку ниже, чтобы открыть двадцать второй урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('make-dream-22','make-dream',22,1,'День 22: Психологическое айкидо','[{"type":"text","markdown":"Вы уже знаете, что всё является ресурсом. Однако, иногда нам приходят такие порции энергии, что мы затрудняемся их гармонично через себя пропустить, и возникает энергетический пробой. Некоторые люди этим пользуются, точно попадая нам в больное место. Данный урок научит Вас выходить из подобных ситуаций, и прочих энергетических наездов, получая при этом дополнительный ресурс."},{"type":"video","vimeoId":"319324127"},{"type":"text","markdown":"\n\n**Стратагема:**"},{"type":"video","vimeoId":"318955576"},{"type":"text","markdown":"\n\n**Задание к уроку:**\nПоэкспериментируйте с приёмами, описанными в уроке. Если Вы действительно открыли для себя что-то новое, то возможность потренироваться представится с самое ближайшее время.\n\n======================\n\n**Ответ на вопрос:**\nЗанимаюсь нумерологией. Люди выливают мне различные проблемы, которые потом крутятся у меня в голове, поедают мои ресурсы. Понимаю, что это не экологично для меня. Как найти золотую середину?"},{"type":"video","vimeoId":"1105074374"}]'::jsonb,'f713d317-34fe-511a-95be-9da227b7dcb6') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('aa6191e3-3211-5e90-b852-49ddfa76e599','78e9961e-3d98-5d62-88e1-549dc368d658','День 23: Практика йоги',23,0,'Осуществи мечту: День 23','{"ru":"Осуществи мечту: День 23"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png" alt="Осуществи мечту" width="504" height="247" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Готовы к практике? Сегодня Вас ждёт нечто особенное. Интереснейший комплекс, требующий минимум времени, но при этом мощно работающий как на уровне тела, так и на уровне энергий.</p><div style="margin:0px 0 0px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-23-4f24ca10a597.jpg" alt="картинка письма" width="504" height="284" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Нажмите кнопку ниже, чтобы открыть двадцать третий урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>Увидимся на коврике!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png\" alt=\"Осуществи мечту\" width=\"504\" height=\"247\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Готовы к практике? Сегодня Вас ждёт нечто особенное. Интереснейший комплекс, требующий минимум времени, но при этом мощно работающий как на уровне тела, так и на уровне энергий.</p><div style=\"margin:0px 0 0px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-23-4f24ca10a597.jpg\" alt=\"картинка письма\" width=\"504\" height=\"284\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Нажмите кнопку ниже, чтобы открыть двадцать третий урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Увидимся на коврике!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-make-dream-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png","alt":"Осуществи мечту","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":294},{"id":"make-dream-23-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Готовы к практике? Сегодня Вас ждёт нечто особенное. Интереснейший комплекс, требующий минимум времени, но при этом мощно работающий как на уровне тела, так и на уровне энергий.</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0},{"id":"make-dream-23-text-image-1","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-23-4f24ca10a597.jpg","alt":"картинка письма","href":"","width":"100%","align":"center","marginTop":0,"marginBottom":0,"naturalWidth":599,"naturalHeight":337},{"id":"make-dream-23-text-2","type":"text","html":"<p>Нажмите кнопку ниже, чтобы открыть двадцать третий урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Увидимся на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('make-dream-23','make-dream',23,1,'День 23: Практика йоги','[{"type":"text","markdown":"Предлагаю Вашему вниманию интереснейший комплекс карама-крамы. В физическом аспекте он развивает гибкость позвоночника, грудной клетки, а также рук по всей длине - от пальцев до плечевых суставов. На энергетическом уровне он гармонизирует стихию огня. А на психологическом уровне способствует удержанию осознанности и баланса.\nЕсли у Вас возникнут затруднения с координацией движений рук, корпуса, ног, дыхания... значит предоставляется возможность потренировать упорство. Когда же Вы освоите этот комплекс, на его выполнение будет требоваться около 10 минут, а пользу Вы будете получать неоценимую!"},{"type":"video","vimeoId":"319281719"},{"type":"text","markdown":"\n\n**Внимание:**\n1. Тщательно разминайтесь/разогревайтесь перед тем, как приступать к выполнению данного комплекса.\n2. Если у Вас есть проблемы с позвоночником, рекомендую проконсультироваться с врачом относительно целесообразности выполнения этого комплекса.\n\n**Стратагема:**"},{"type":"video","vimeoId":"1249171422"},{"type":"text","markdown":"\n\n**Задание:**\nОсваивайте данный комплекс :)"}]'::jsonb,'aa6191e3-3211-5e90-b852-49ddfa76e599') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('036786b4-a792-51f9-a902-b89c188404d6','78e9961e-3d98-5d62-88e1-549dc368d658','День 24: Стратагема',24,0,'Осуществи мечту: День 24','{"ru":"Осуществи мечту: День 24"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png" alt="Осуществи мечту" width="504" height="247" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Освойте ещё один хитрый приём достижения цели - новую стратагему.</p><div style="margin:0px 0 0px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-24-f14fcd4e94f6.jpg" alt="картинка письма" width="504" height="284" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Нажмите кнопку ниже, чтобы открыть двадцать четвёртый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>Продуктивного дня!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png\" alt=\"Осуществи мечту\" width=\"504\" height=\"247\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Освойте ещё один хитрый приём достижения цели - новую стратагему.</p><div style=\"margin:0px 0 0px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-24-f14fcd4e94f6.jpg\" alt=\"картинка письма\" width=\"504\" height=\"284\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Нажмите кнопку ниже, чтобы открыть двадцать четвёртый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Продуктивного дня!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-make-dream-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png","alt":"Осуществи мечту","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":294},{"id":"make-dream-24-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Освойте ещё один хитрый приём достижения цели - новую стратагему.</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0},{"id":"make-dream-24-text-image-1","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-24-f14fcd4e94f6.jpg","alt":"картинка письма","href":"","width":"100%","align":"center","marginTop":0,"marginBottom":0,"naturalWidth":599,"naturalHeight":337},{"id":"make-dream-24-text-2","type":"text","html":"<p>Нажмите кнопку ниже, чтобы открыть двадцать четвёртый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Продуктивного дня!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
