insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('839e48d1-b8da-5282-93d7-7f0e99abd50f','78e9961e-3d98-5d62-88e1-549dc368d658','День 30: Стратагема',30,0,'Осуществи мечту: День 30','{"ru":"Осуществи мечту: День 30"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png" alt="Осуществи мечту" width="504" height="247" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Порой срабатывают удивительные вещи. И данная стратагема - достойный тому пример.</p><div style="margin:0px 0 0px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-30-cc1fd634773b.jpg" alt="картинка письма" width="504" height="284" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Нажмите кнопку ниже, чтобы открыть тридцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>Успешного дня!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png\" alt=\"Осуществи мечту\" width=\"504\" height=\"247\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Порой срабатывают удивительные вещи. И данная с