insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('f71a2953-cef0-5cd6-b4bc-03cfddadb188','78e9961e-3d98-5d62-88e1-549dc368d658','День 32: Стратагема',32,0,'Осуществи мечту: День 32','{"ru":"Осуществи мечту: День 32"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png" alt="Осуществи мечту" width="504" height="247" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня я предлагаю Вашему вниманию интереснейшую стратагему - об использовании пустоты, а также дополнительный урок о том, как нужно подходить к практике йоги.</p><div style="margin:0px 0 0px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-32-c9ed26abf209.jpg" alt="картинка письма" width="504" height="284" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Нажмите кнопку ниже, чтобы открыть тридцать второй урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>Творческого настроения!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png\" alt=\"Осуществи мечту\" width=\"504\" height=\"247\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня я предлагаю Вашему вниманию интереснейшую стратагему - об использовании пустоты, а также дополнительный урок о том, как нужно подходить к практике йоги.</p><div style=\"margin:0px 0 0px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-32-c9ed26abf209.jpg\" alt=\"картинка письма\" width=\"504\" height=\"284\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Нажмите кнопку ниже, чтобы открыть тридцать второй урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Творческого настроения!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-make-dream-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png","alt":"Осуществи мечту","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":294},{"id":"make-dream-32-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня я предлагаю Вашему вниманию интереснейшую стратагему - об использовании пустоты, а также дополнительный урок о том, как нужно подходить к практике йоги.</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0},{"id":"make-dream-32-text-image-1","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-32-c9ed26abf209.jpg","alt":"картинка письма","href":"","width":"100%","align":"center","marginTop":0,"marginBottom":0,"naturalWidth":599,"naturalHeight":337},{"id":"make-dream-32-text-2","type":"text","html":"<p>Нажмите кнопку ниже, чтобы открыть тридцать второй урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Творческого настроения!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('make-dream-32','make-dream',32,1,'День 32: Стратагема','[{"type":"video","vimeoId":"320205306"},{"type":"text","markdown":"\n\nА также предлагаю Вашему вниманию урок о том, как нужно подходить к практике йоги. В качестве примера я выполнил в нём тот динамический комплекс, который мы осваивали на прошлой неделе (надеюсь, он Вам понравился). Но на его месте может быть любой другой комплекс асан."},{"type":"video","vimeoId":"1105076207"}]'::jsonb,'f71a2953-cef0-5cd6-b4bc-03cfddadb188') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('c302d847-b6d0-5bd4-a7e6-9a0c30da7902','78e9961e-3d98-5d62-88e1-549dc368d658','День 33: Стратагема',33,0,'Осуществи мечту: День 33','{"ru":"Осуществи мечту: День 33"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png" alt="Осуществи мечту" width="504" height="247" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Освойте новую стратагему - о том как посеять раздор и внести сумятицу.</p><div style="margin:0px 0 0px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-33-96b5ecdc3093.jpg" alt="картинка письма" width="504" height="284" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Нажмите кнопку ниже, чтобы открыть тридцать третий урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>Продуктивного дня!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png\" alt=\"Осуществи мечту\" width=\"504\" height=\"247\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Освойте новую стратагему - о том как посеять раздор и внести сумятицу.</p><div style=\"margin:0px 0 0px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-33-96b5ecdc3093.jpg\" alt=\"картинка письма\" width=\"504\" height=\"284\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Нажмите кнопку ниже, чтобы открыть тридцать третий урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Продуктивного дня!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-make-dream-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png","alt":"Осуществи мечту","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":294},{"id":"make-dream-33-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Освойте новую стратагему - о том как посеять раздор и внести сумятицу.</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0},{"id":"make-dream-33-text-image-1","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-33-96b5ecdc3093.jpg","alt":"картинка письма","href":"","width":"100%","align":"center","marginTop":0,"marginBottom":0,"naturalWidth":599,"naturalHeight":337},{"id":"make-dream-33-text-2","type":"text","html":"<p>Нажмите кнопку ниже, чтобы открыть тридцать третий урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Продуктивного дня!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('make-dream-33','make-dream',33,1,'День 33: Стратагема','[{"type":"video","vimeoId":"320205995"}]'::jsonb,'c302d847-b6d0-5bd4-a7e6-9a0c30da7902') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('2105fc93-ffa7-5d8c-a950-069780638edd','78e9961e-3d98-5d62-88e1-549dc368d658','День 34: Стратагема',34,0,'Осуществи мечту: День 34','{"ru":"Осуществи мечту: День 34"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png" alt="Осуществи мечту" width="504" height="247" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Вроде как никто не ведёт игру против себя. Однако, сегодня Вам предстоит освоить стратагему, которая учит это делать (разумеется, чтобы победить).</p><div style="margin:0px 0 0px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-34-0029e07387d9.jpg" alt="картинка письма" width="504" height="284" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Нажмите кнопку ниже, чтобы открыть тридцать четвёртый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>Особенного дня!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png\" alt=\"Осуществи мечту\" width=\"504\" height=\"247\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Вроде как никто не ведёт игру против себя. Однако, сегодня Вам предстоит освоить стратагему, которая учит это делать (разумеется, чтобы победить).</p><div style=\"margin:0px 0 0px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-34-0029e07387d9.jpg\" alt=\"картинка письма\" width=\"504\" height=\"284\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Нажмите кнопку ниже, чтобы открыть тридцать четвёртый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Особенного дня!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-make-dream-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png","alt":"Осуществи мечту","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":294},{"id":"make-dream-34-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Вроде как никто не ведёт игру против себя. Однако, сегодня Вам предстоит освоить стратагему, которая учит это делать (разумеется, чтобы победить).</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0},{"id":"make-dream-34-text-image-1","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-34-0029e07387d9.jpg","alt":"картинка письма","href":"","width":"100%","align":"center","marginTop":0,"marginBottom":0,"naturalWidth":599,"naturalHeight":337},{"id":"make-dream-34-text-2","type":"text","html":"<p>Нажмите кнопку ниже, чтобы открыть тридцать четвёртый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Особенного дня!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
