insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('2c3ff185-963f-5fbd-9219-fa2509c13f2d','78e9961e-3d98-5d62-88e1-549dc368d658','День 35: Стратагема',35,0,'Осуществи мечту: День 35','{"ru":"Осуществи мечту: День 35"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png" alt="Осуществи мечту" width="504" height="247" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня я предлагаю Вам освоить стратагему цепи.</p><div style="margin:0px 0 0px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-35-63df52bb1b71.jpg" alt="картинка письма" width="504" height="284" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Нажмите кнопку ниже, чтобы открыть тридцать пятый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>Успешного дня!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png\" alt=\"Осуществи мечту\" width=\"504\" height=\"247\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня я предлагаю Вам освоить стратагему цепи.</p><div style=\"margin:0px 0 0px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-35-63df52bb1b71.jpg\" alt=\"картинка письма\" width=\"504\" height=\"284\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Нажмите кнопку ниже, чтобы открыть тридцать пятый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Успешного дня!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-make-dream-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png","alt":"Осуществи мечту","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":294},{"id":"make-dream-35-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня я предлагаю Вам освоить стратагему цепи.</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0},{"id":"make-dream-35-text-image-1","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-35-63df52bb1b71.jpg","alt":"картинка письма","href":"","width":"100%","align":"center","marginTop":0,"marginBottom":0,"naturalWidth":599,"naturalHeight":337},{"id":"make-dream-35-text-2","type":"text","html":"<p>Нажмите кнопку ниже, чтобы открыть тридцать пятый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Успешного дня!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('make-dream-35','make-dream',35,1,'День 35: Стратагема','[{"type":"video","vimeoId":"320206190"}]'::jsonb,'2c3ff185-963f-5fbd-9219-fa2509c13f2d') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('3a744115-507d-5f3a-a111-a90a04e81ff9','78e9961e-3d98-5d62-88e1-549dc368d658','День 36: Стратагема',36,0,'Осуществи мечту: День 36','{"ru":"Осуществи мечту: День 36"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png" alt="Осуществи мечту" width="504" height="247" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня у нас заключительный день курса!</p><p></p><p>Предлагаю Вам стратагему 36, суть которой в том, что в некоторых случаях лучше убежать, а также ещё один урок на дорожку.</p><div style="margin:0px 0 0px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-36-ccb27fc08472.jpg" alt="картинка письма" width="504" height="284" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Нажмите кнопку ниже, чтобы открыть тридцать шестой урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>Даже не верится, что курс уже заканчивается. Подобные интенсивные курсы хороши тем, что вырабатывают привычку каждый день делать шаг на пути развития. И теперь сформулируйте для себя намерение не забрасывать практику. Продолжайте двигаться вперёд. Лучше делать маленький шаг каждый день, чем большой шаг дважды в неделю, или вообще ничего не делать, надеясь, что жизнь станет лучше сама собой.</p><p></p><p>Имейте в виду, что я подготовил всесторонний комплект практикумов и курсов, которые могут быть вам полезны. Чтобы выбрать то, что вам подойдёт, сначала вам нужно определиться с направлением - то есть честно осознать какая сфера жизни (или ситуации) сейчас вас более всего трогает (вызывает дискомфорт, или, наоборот, воодушевляет), а затем решить сколько времени вы готовы посвятить урокам и практикам. Ниже я перечислил практикумы и курсы, которые могут вас заинтересовать:</p><p></p><p>ПРАКТИКУМЫ:<br>- Месяц здоровья: <a href="https://zamkovoi.yoga/m1">https://zamkovoi.yoga/m1</a><br>- Месяц наслаждений: <a href="https://zamkovoi.yoga/m2">https://zamkovoi.yoga/m2</a><br>- Месяц силы: <a href="https://zamkovoi.yoga/m3">https://zamkovoi.yoga/m3</a><br>- Месяц любви: <a href="https://zamkovoi.yoga/m4">https://zamkovoi.yoga/m4</a><br>- Месяц свободы: <a href="https://zamkovoi.yoga/m5">https://zamkovoi.yoga/m5</a><br>- Месяц мудрости: <a href="https://zamkovoi.yoga/m6">https://zamkovoi.yoga/m6</a><br>- Месяц святости: <a href="https://zamkovoi.yoga/m7">https://zamkovoi.yoga/m7</a></p><p></p><p>КУРСЫ:<br>- Йога и здоровье: <a href="https://zamkovoi.yoga/yoga1">https://zamkovoi.yoga/yoga1</a><br>- Йога плюс женственность: <a href="https://zamkovoi.yoga/yoga2">https://zamkovoi.yoga/yoga2</a><br>- Тантра - мистерия взаимоотношений: <a href="https://zamkovoi.yoga/tantra12">https://zamkovoi.yoga/tantra12</a><br>- Осуществи мечту: <a href="https://zamkovoi.yoga/yoga3">https://zamkovoi.yoga/yoga3</a><br>- Планета любви: <a href="https://zamkovoi.yoga/yoga4">https://zamkovoi.yoga/yoga4</a><br>- Источник творческой силы: <a href="https://zamkovoi.yoga/yoga5">https://zamkovoi.yoga/yoga5</a><br>- 36 шагов йоги: <a href="https://zamkovoi.yoga/yoga36">https://zamkovoi.yoga/yoga36</a><br>- Путь души: <a href="https://zamkovoi.yoga/yogas">https://zamkovoi.yoga/yogas</a></p><p></p><p>Желаю Вам дальнейшего развития!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png\" alt=\"Осуществи мечту\" width=\"504\" height=\"247\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня у нас заключительный день курса!</p><p></p><p>Предлагаю Вам стратагему 36, суть которой в том, что в некоторых случаях лучше убежать, а также ещё один урок на дорожку.</p><div style=\"margin:0px 0 0px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-36-ccb27fc08472.jpg\" alt=\"картинка письма\" width=\"504\" height=\"284\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Нажмите кнопку ниже, чтобы открыть тридцать шестой урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Даже не верится, что курс уже заканчивается. Подобные интенсивные курсы хороши тем, что вырабатывают привычку каждый день делать шаг на пути развития. И теперь сформулируйте для себя намерение не забрасывать практику. Продолжайте двигаться вперёд. Лучше делать маленький шаг каждый день, чем большой шаг дважды в неделю, или вообще ничего не делать, надеясь, что жизнь станет лучше сама собой.</p><p></p><p>Имейте в виду, что я подготовил всесторонний комплект практикумов и курсов, которые могут быть вам полезны. Чтобы выбрать то, что вам подойдёт, сначала вам нужно определиться с направлением - то есть честно осознать какая сфера жизни (или ситуации) сейчас вас более всего трогает (вызывает дискомфорт, или, наоборот, воодушевляет), а затем решить сколько времени вы готовы посвятить урокам и практикам. Ниже я перечислил практикумы и курсы, которые могут вас заинтересовать:</p><p></p><p>ПРАКТИКУМЫ:<br>- Месяц здоровья: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br>- Месяц наслаждений: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br>- Месяц силы: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br>- Месяц любви: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br>- Месяц свободы: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br>- Месяц мудрости: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br>- Месяц святости: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a></p><p></p><p>КУРСЫ:<br>- Йога и здоровье: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br>- Йога плюс женственность: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br>- Тантра - мистерия взаимоотношений: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br>- Осуществи мечту: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br>- Планета любви: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br>- Источник творческой силы: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br>- 36 шагов йоги: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br>- Путь души: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a></p><p></p><p>Желаю Вам дальнейшего развития!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-make-dream-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png","alt":"Осуществи мечту","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":294},{"id":"make-dream-36-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня у нас заключительный день курса!</p><p></p><p>Предлагаю Вам стратагему 36, суть которой в том, что в некоторых случаях лучше убежать, а также ещё один урок на дорожку.</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0},{"id":"make-dream-36-text-image-1","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-36-ccb27fc08472.jpg","alt":"картинка письма","href":"","width":"100%","align":"center","marginTop":0,"marginBottom":0,"naturalWidth":599,"naturalHeight":337},{"id":"make-dream-36-text-2","type":"text","html":"<p>Нажмите кнопку ниже, чтобы открыть тридцать шестой урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Даже не верится, что курс уже заканчивается. Подобные интенсивные курсы хороши тем, что вырабатывают привычку каждый день делать шаг на пути развития. И теперь сформулируйте для себя намерение не забрасывать практику. Продолжайте двигаться вперёд. Лучше делать маленький шаг каждый день, чем большой шаг дважды в неделю, или вообще ничего не делать, надеясь, что жизнь станет лучше сама собой.</p><p></p><p>Имейте в виду, что я подготовил всесторонний комплект практикумов и курсов, которые могут быть вам полезны. Чтобы выбрать то, что вам подойдёт, сначала вам нужно определиться с направлением - то есть честно осознать какая сфера жизни (или ситуации) сейчас вас более всего трогает (вызывает дискомфорт, или, наоборот, воодушевляет), а затем решить сколько времени вы готовы посвятить урокам и практикам. Ниже я перечислил практикумы и курсы, которые могут вас заинтересовать:</p><p></p><p>ПРАКТИКУМЫ:<br>- Месяц здоровья: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br>- Месяц наслаждений: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br>- Месяц силы: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br>- Месяц любви: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br>- Месяц свободы: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br>- Месяц мудрости: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br>- Месяц святости: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a></p><p></p><p>КУРСЫ:<br>- Йога и здоровье: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br>- Йога плюс женственность: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br>- Тантра - мистерия взаимоотношений: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br>- Осуществи мечту: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br>- Планета любви: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br>- Источник творческой силы: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br>- 36 шагов йоги: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br>- Путь души: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a></p><p></p><p>Желаю Вам дальнейшего развития!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('make-dream-36','make-dream',36,1,'День 36: Стратагема','[{"type":"video","vimeoId":"1249171218"},{"type":"text","markdown":"\n\nИ пришло время заключительного урока курса:"},{"type":"video","vimeoId":"322576683"}]'::jsonb,'3a744115-507d-5f3a-a111-a90a04e81ff9') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('9c553703-9fd8-5fc9-8798-d8b2c0481257','78e9961e-3d98-5d62-88e1-549dc368d658','День 37: Практика исполнения желаний',37,0,'Осуществи мечту: Практика исполнения желаний','{"ru":"Осуществи мечту: Практика исполнения желаний"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png" alt="Осуществи мечту" width="504" height="247" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я решил дополнительно к курсу открыть вам доступ к записи практики, направленной на исполнение желаний уровня манипуры. Уверен, что она будет вам полезна и поможет практиковать йогу эффективней.</p><div style="margin:0px 0 0px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-37-8e0b1cd308be.jpg" alt="картинка письма" width="504" height="284" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Нажмите кнопку ниже, чтобы открыть тридцать седьмой урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>Исполнения желаний!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png\" alt=\"Осуществи мечту\" width=\"504\" height=\"247\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я решил дополнительно к курсу открыть вам доступ к записи практики, направленной на исполнение желаний уровня манипуры. Уверен, что она будет вам полезна и поможет практиковать йогу эффективней.</p><div style=\"margin:0px 0 0px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-37-8e0b1cd308be.jpg\" alt=\"картинка письма\" width=\"504\" height=\"284\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Нажмите кнопку ниже, чтобы открыть тридцать седьмой урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Исполнения желаний!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-make-dream-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/make-dream_email-e47ce2922380.png","alt":"Осуществи мечту","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":294},{"id":"make-dream-37-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Я решил дополнительно к курсу открыть вам доступ к записи практики, направленной на исполнение желаний уровня манипуры. Уверен, что она будет вам полезна и поможет практиковать йогу эффективней.</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0},{"id":"make-dream-37-text-image-1","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/make-dream/letter-37-8e0b1cd308be.jpg","alt":"картинка письма","href":"","width":"100%","align":"center","marginTop":0,"marginBottom":0,"naturalWidth":599,"naturalHeight":337},{"id":"make-dream-37-text-2","type":"text","html":"<p>Нажмите кнопку ниже, чтобы открыть тридцать седьмой урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Исполнения желаний!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('make-dream-37','make-dream',37,1,'День 37: Практика исполнения желаний','[{"type":"text","markdown":"В новогодние праздники я провёл три практики йоги, направленные на исполнение желаний в трёх сферах: здоровье, деньги и любовь - то есть на уровне соответствующих чакр - муладхары, манипуры и анахаты. И сегодня я предлагаю вам выполнить практику, направленную на исполнение желаний, связанных с поступающим к вам денежным потоком и всем, что с ним связано - заработком (ваш или супруга), профессиональным ростом, социальной реализацией, развитием бизнеса и т.п. Я уверен, что она принесёт плоды не только в плане здоровья, но и в плане лучшего понимания эффективной практики йогой."},{"type":"video","vimeoId":"662347896"},{"type":"text","markdown":"\n\nЧтобы получить две другие практики исполнения желаний, перейдите на ссылке - https://zamkovoi.ru/3z2/"}]'::jsonb,'9c553703-9fd8-5fc9-8798-d8b2c0481257') on conflict(id) do nothing;
